<?php
declare(strict_types=1);
function handle_leaderboard_route(string $method,string $path):bool{if($path!=='/leaderboard')return false;if($method!=='GET')method_not_allowed(['GET']);leaderboard_index();return true;}
function leaderboard_index():void{$pdo=Database::pdo();$a=require_auth();$uid=(int)$a['user']['id'];$limit=max(1,min(100,(int)($_GET['limit']??20)));$sql='SELECT u.id,u.name,p.level_number,p.level_title,(p.current_xp+(p.level_number*p.required_xp)) AS total_xp FROM user_profiles p JOIN users u ON u.id=p.user_id WHERE u.status="active" ORDER BY total_xp DESC,p.level_number DESC,p.current_xp DESC,u.created_at ASC LIMIT :limit';$st=$pdo->prepare($sql);$st->bindValue(':limit',$limit,PDO::PARAM_INT);$st->execute();$items=[];$rank=1;$me=null;foreach($st->fetchAll()as$r){$it=['rank'=>$rank,'name'=>$r['name'],'levelNumber'=>(int)$r['level_number'],'levelTitle'=>$r['level_title'],'totalXp'=>(int)$r['total_xp'],'isMe'=>((int)$r['id']===$uid)];if($it['isMe'])$me=$it;$items[]=$it;$rank++;}if($me===null){$st=$pdo->prepare('SELECT u.id,u.name,p.level_number,p.level_title,(p.current_xp+(p.level_number*p.required_xp)) AS total_xp FROM user_profiles p JOIN users u ON u.id=p.user_id WHERE u.id=? LIMIT 1');$st->execute([$uid]);$c=$st->fetch();if($c){$score=(int)$c['total_xp'];$st=$pdo->prepare('SELECT COUNT(*) AS c FROM user_profiles p JOIN users u ON u.id=p.user_id WHERE u.status="active" AND (p.current_xp+(p.level_number*p.required_xp))>?');$st->execute([$score]);$higher=(int)($st->fetch()['c']??0);$me=['rank'=>$higher+1,'name'=>$c['name'],'levelNumber'=>(int)$c['level_number'],'levelTitle'=>$c['level_title'],'totalXp'=>$score,'isMe'=>true];}}success_response(['items'=>$items,'me'=>$me,'limit'=>$limit]);}
